fn fetch(url: &str) -> Result<String, Box<dyn std::error::Error>> {
    let client = reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_secs(10)).build()?;
    let response = client.get(url).send()?;
    if !response.status().is_success() {
        return Err(format!("HTTP {}", response.status()).into());
    }
    Ok(response.text()?)
}

std::string read_text(const std::string& path) {
    std::ifstream input(path, std::ios::binary);
    if (!input) throw std::runtime_error("open failed");
    std::string text;
    char c;
    while (input.get(c)) text.push_back(c);
    if (input.bad() || !input.eof()) throw std::runtime_error("read failed");
    return text;
}

void write_text(const std::string& path, const std::string& utf8_bytes) {
    std::ofstream output(path, std::ios::binary | std::ios::trunc);
    output.exceptions(std::ios::failbit | std::ios::badbit);
    output << utf8_bytes;
    output.close();
}

