#include <curl/curl.h>
#include <iostream>
int main() {
    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) return 1;
    CURL* handle = curl_easy_init();
    if (!handle) { curl_global_cleanup(); return 1; }
    CURLcode result = curl_easy_setopt(handle, CURLOPT_URL, "https://example.com");
    if (result == CURLE_OK)
        result = curl_easy_setopt(handle, CURLOPT_TIMEOUT, 10L);
    if (result == CURLE_OK) result = curl_easy_perform(handle);
    long status = 0;
    if (result == CURLE_OK)
        result = curl_easy_getinfo(handle, CURLINFO_RESPONSE_CODE, &status);
    bool ok = result == CURLE_OK && status >= 200 && status < 300;
    if (!ok) std::cerr << "Transfer " << result << ", HTTP " << status << '\n';
    curl_easy_cleanup(handle);
    curl_global_cleanup();
    return ok ? 0 : 1;
}
